-- Add the compliance items a marae is missing, from the Marae Governance and Compliance Framework (v0.4 wording, as already used on other marae).
-- Insert-only and idempotent: a row is added only if no item with the same name exists. Existing items, their dates, history and wording are never changed.
-- Every item states when it applies (its notes begin 'Applies if: ...'), and items still To verify say so.
insert into public.compliance_items (category, name, renewal_months, notes, classification, legal_basis, legal_basis_detail, stage)
select v.category, v.name, v.renewal_months, v.notes, v.classification, v.legal_basis, v.legal_basis_detail, v.stage
from (values
  ($q$building$q$,$q$Building Warrant of Fitness$q$,12,null,$q$task$q$,$q$Building Act 2004 ss 100-108 — compliance schedules and annual Building Warrant of Fitness$q$,$q$Required only if your building has a compliance schedule, which applies to any building other than a single home that has a fire alarm or other specified system. The owner supplies the Building Warrant of Fitness to the council each year on the anniversary of the compliance schedule. Source: building.govt.nz (read 12 Nov 2026).$q$,2),
  ($q$emergency_preparedness$q$,$q$Fire alarms — tested and detection confirmed working$q$,6,null,$q$task$q$,$q$Building Act 2004 — compliance schedule and annual Building Warrant of Fitness (if the building has a fire alarm or other specified system)$q$,$q$Any building other than a single home that has a fire alarm or other specified system must have a compliance schedule and give the council an annual Building Warrant of Fitness. Check whether your building has a compliance schedule. Source: building.govt.nz (read 12 Nov 2026).$q$,1),
  ($q$emergency_preparedness$q$,$q$Marae decision recorded: how safety measures are applied in the wharenui and tapu spaces$q$,null,$q$Framework v0.4 [EM4] · Applies if: all marae. · Verification: Practice (no legal source). · Frequency: When measures change. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Framework v0.4 (tikanga stays with the marae)$q$,$q$Good practice or a marae decision – not a legal requirement.$q$,3),
  ($q$emergency_preparedness$q$,$q$Marae decision recorded: role as an emergency hub and who decides when it opens$q$,12,$q$Framework v0.4 [EM3] · Applies if: all marae. · Verification: Practice (no legal source). · Frequency: Annual. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Framework v0.4, 4.2$q$,$q$Good practice or a marae decision – not a legal requirement.$q$,3),
  ($q$emergency_preparedness$q$,$q$Written evacuation procedure for each building the public is admitted to$q$,12,$q$Framework v0.4 [FR1] · Applies if: a building is open to the public or is a place of assembly (wharenui, wharekai, hall). · Verification: Verified – primary source. · Frequency: Review annually (suggested). · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$FENZ Regulations 2018, Schedule 2 and regs 5–17$q$,$q$Checked against the regulation or Act text (read via a summary on 12 Nov 2026; re-open the section before relying on it).$q$,1),
  ($q$health_safety$q$,$q$As an employer: duty to keep workers and others safe confirmed with WorkSafe$q$,12,$q$Framework v0.4 [HS2] · Applies if: you employ anyone on an employment agreement. · Verification: Partly verified. · Frequency: Annual. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Health and Safety at Work Act 2015, s 36; WorkSafe$q$,$q$Partly confirmed; part of this is still being checked.$q$,2),
  ($q$health_safety$q$,$q$As an employer: trustees checked whether the officer due diligence duty applies$q$,null,$q$Framework v0.4 [HS3] · Applies if: you employ anyone on an employment agreement. · Verification: Partly verified (s 18 text read 22 Nov 2026; whether your trustees count as officers depends on whether you employ people; confirm with WorkSafe). · Frequency: Once, then on any change. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Health and Safety at Work Act 2015, ss 18 and 44$q$,$q$Confirmed on official WorkSafe guidance (12 Nov 2026): the due diligence duty is owed by officers of a business or undertaking, and volunteer officers have the duty but commit no offence if they fall short. A marae with no employees is not a business or undertaking. Still open: whether trustees of a marae that employs people count as officers under s 18. Confirm with WorkSafe.$q$,2),
  ($q$health_safety$q$,$q$Health & Safety Policy Review$q$,12,null,$q$task$q$,$q$Health and Safety at Work Act 2015 if the marae has employees; otherwise good practice$q$,$q$A marae with employees is a business or undertaking with legal duties. A volunteer-only marae has no duties under the Act but a policy still protects everyone. Confirm with WorkSafe.$q$,2),
  ($q$health_safety$q$,$q$Recorded whether the marae employs anyone on an employment agreement$q$,12,$q$Framework v0.4 [HS1] · Applies if: all marae. · Verification: Verified – official guidance. · Frequency: Annual and on any change. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$WorkSafe, Keeping volunteers healthy and safe (Sept 2024)$q$,$q$Confirmed on an official agency page (12 Nov 2026).$q$,1),
  ($q$health_safety$q$,$q$Volunteer safety induction done; incident and near-miss register kept$q$,12,$q$Framework v0.4 [HS4] · Applies if: all marae. · Verification: Partly verified. · Frequency: Each volunteer; register ongoing. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$WorkSafe volunteers guidance; common-law duty of care$q$,$q$Partly confirmed; part of this is still being checked.$q$,3),
  ($q$insurance$q$,$q$Building & Contents Insurance$q$,12,null,$q$task$q$,$q$Good practice (no law requires it)$q$,$q$Protects the marae's buildings and contents if there is a fire, storm or flood. Funders, lenders or hirers may also require it. A marae decision.$q$,2),
  ($q$insurance$q$,$q$Public Liability Insurance$q$,12,null,$q$task$q$,$q$Good practice (no law requires it)$q$,$q$Covers the marae if someone is injured or property is damaged at an event. Funders and hirers often ask for proof of cover. A marae decision.$q$,2),
  ($q$other$q$,$q$Changes notified to Charities Services within 3 months (name, address, balance date, rules, purposes, officers)$q$,null,$q$Framework v0.4 [CH2] · Applies if: your marae is a registered charity. · Verification: Verified – official guidance. · Frequency: Within 3 months of each change. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Charities Services – update your charity details$q$,$q$Confirmed on an official agency page (12 Nov 2026).$q$,2),
  ($q$other$q$,$q$Charities annual return and performance report filed within 6 months of balance date$q$,12,$q$Framework v0.4 [CH1] · Applies if: your marae is a registered charity. · Verification: Verified – official guidance. · Frequency: Annual. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Charities Act 2005; Charities Services$q$,$q$Confirmed on an official agency page (12 Nov 2026).$q$,2),
  ($q$other$q$,$q$Governance procedures reviewed in the last 3 years$q$,36,$q$Framework v0.4 [CH3] · Applies if: your marae is a registered charity. · Verification: Partly verified. · Frequency: Every 3 years (expectation, not confirmed as a legal duty). · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Charities Services annual return question$q$,$q$Partly confirmed; part of this is still being checked.$q$,3),
  ($q$other$q$,$q$Trustee records backed up and a restore tested$q$,12,$q$Framework v0.4 [IN1] · Applies if: all marae. · Verification: Practice (no legal source). · Frequency: Test annually. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Framework v0.4, Area 6$q$,$q$Good practice or a marae decision – not a legal requirement.$q$,3),
  ($q$trustee$q$,$q$Accurate, separate, up-to-date records of the reservation's administration kept$q$,12,$q$Framework v0.4 [GV7] · Applies if: your marae land is a Māori reservation. · Verification: Verified – primary source. · Frequency: Ongoing; review quarterly. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Māori Reservations Regulations 1994, reg 15$q$,$q$Checked against the regulation or Act text (full text of the version as at 9 January 2025 read on 22 Nov 2026).$q$,2),
  ($q$trustee$q$,$q$Annual meeting held with at least 21 days' notice, open to beneficiaries$q$,12,$q$Framework v0.4 [GV5] · Applies if: your marae land is a Māori reservation. · Verification: Verified – primary source. · Frequency: Annual. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Māori Reservations Regulations 1994, reg 19 (as amended 2025)$q$,$q$Checked against the regulation or Act text (full text of the version as at 9 January 2025 read on 22 Nov 2026).$q$,2),
  ($q$trustee$q$,$q$Conflicts of interest register kept and on the meeting agenda$q$,12,$q$Framework v0.4 [GV10] · Applies if: all marae. · Verification: To verify. · Frequency: Each meeting. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Framework v0.4, 1.3 (legal in some structures – not yet researched)$q$,$q$NOT YET VERIFIED – treat as a question to confirm, not a rule.$q$,3),
  ($q$trustee$q$,$q$Current list of trustees with appointment and term end dates$q$,null,$q$Framework v0.4 [GV9] · Applies if: all marae. · Verification: Practice (no legal source). · Frequency: Each change. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Framework v0.4, 1.3$q$,$q$Good practice or a marae decision – not a legal requirement.$q$,3),
  ($q$trustee$q$,$q$First trustee meeting within 30 days of appointment; minute book kept$q$,null,$q$Framework v0.4 [GV4] · Applies if: your marae land is a Māori reservation and your trustees are not a body corporate (if a body corporate is the trustee, reg 16 applies instead). · Verification: Verified – primary source. · Frequency: Each appointment; minutes each meeting. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Māori Reservations Regulations 1994, reg 17$q$,$q$Checked against the regulation or Act text (full text of the version as at 9 January 2025 read on 22 Nov 2026).$q$,2),
  ($q$trustee$q$,$q$Marae charter — written with beneficiaries; signed copy located (good practice)$q$,null,$q$Framework v0.4 [GV2] · Applies if: your marae land is a Māori reservation. · Verification: Verified – primary source (full text read 22 Nov 2026). The regulation says the charter is drawn up with the beneficiaries; it does not require signing, so a signed copy is good practice. · Frequency: Review date set by the marae. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Māori Reservations Regulations 1994, reg 7$q$,$q$Checked against the regulation or Act text (full text of the version as at 9 January 2025 read on 22 Nov 2026).$q$,2),
  ($q$trustee$q$,$q$Notice of each trustee appointment published in a local newspaper within 7 days$q$,null,$q$Framework v0.4 [GV1] · Applies if: your marae land is a Māori reservation. · Verification: Verified – primary source. · Frequency: Each appointment. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Māori Reservations Regulations 1994, reg 4$q$,$q$Checked against the regulation or Act text (full text of the version as at 9 January 2025 read on 22 Nov 2026).$q$,2),
  ($q$trustee$q$,$q$Reservation money in a separate bank account with at least two authorised signatories$q$,12,$q$Framework v0.4 [GV6] · Applies if: your marae land is a Māori reservation. · Verification: Verified – primary source. · Frequency: Annual check. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Māori Reservations Regulations 1994, reg 15$q$,$q$Checked against the regulation or Act text (full text of the version as at 9 January 2025 read on 22 Nov 2026).$q$,1),
  ($q$trustee$q$,$q$Succession plan for trustees and key volunteers agreed$q$,12,$q$Framework v0.4 [GV11] · Applies if: all marae. · Verification: Practice (no legal source). · Frequency: Annual. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Framework v0.4, 1.3$q$,$q$Good practice or a marae decision – not a legal requirement.$q$,3),
  ($q$trustee$q$,$q$Trustees know the terms of the trust and their five mandatory duties$q$,12,$q$Framework v0.4 [GV8] · Applies if: your marae is governed through a trust. · Verification: Verified – primary source. · Frequency: Each new trustee; annual reminder. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Trusts Act 2019, ss 23–27$q$,$q$Checked against the regulation or Act text (read via a summary on 12 Nov 2026; re-open the section before relying on it).$q$,2),
  ($q$trustee$q$,$q$Trustees know their duty to act in good faith and run the reservation for its purposes$q$,null,$q$Framework v0.4 [GV3] · Applies if: your marae land is a Māori reservation. · Verification: Verified – primary source. · Frequency: Each new trustee. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Māori Reservations Regulations 1994, reg 6$q$,$q$Checked against the regulation or Act text (full text of the version as at 9 January 2025 read on 22 Nov 2026).$q$,2),
  ($q$water$q$,$q$Water assessment recorded: source, who is supplied, how many people$q$,null,$q$Framework v0.4 [WT1] · Applies if: all marae. · Verification: Practice (no legal source). · Frequency: Once, then on any change. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Framework v0.4 (drinking water)$q$,$q$Good practice or a marae decision – not a legal requirement.$q$,1)
) as v(category, name, renewal_months, notes, classification, legal_basis, legal_basis_detail, stage)
where not exists (select 1 from public.compliance_items i where i.name = v.name);
